function showLoading(text = '加载中...'){let overlay = document.getElementById('loadingOverlay');if(!overlay){overlay = document.createElement('div');overlay.id = 'loadingOverlay';overlay.className = 'loading-overlay';overlay.innerHTML = ` <div style="text-align:center;"> <div class="loading-spinner"></div> <div class="loading-text">${text}</div> </div> `;document.body.appendChild(overlay);}else{const loadingText = overlay.querySelector('.loading-text');if(loadingText)loadingText.textContent = text;}overlay.classList.add('show');}function hideLoading(){const overlay = document.getElementById('loadingOverlay');if(overlay){overlay.classList.remove('show');}}let toastContainer = null;function initToastContainer(){if(!toastContainer){toastContainer = document.createElement('div');toastContainer.className = 'toast-container';document.body.appendChild(toastContainer);}}function showToast(message,type = 'info',duration = 3000){initToastContainer();const icons ={success:'fas fa-check-circle',error:'fas fa-times-circle',warning:'fas fa-exclamation-triangle',info:'fas fa-info-circle'};const toast = document.createElement('div');toast.className = `toast ${type}`;toast.innerHTML = ` <i class="toast-icon ${icons[type]}"></i> <div class="toast-message">${message}</div> <button class="toast-close" onclick="closeToast(this.parentElement)">&times;</button> `;toastContainer.appendChild(toast);if(duration > 0){setTimeout(()=>{closeToast(toast);},duration);}return toast;}function closeToast(toast){if(!toast || toast.classList.contains('hiding'))return;toast.classList.add('hiding');setTimeout(()=>{if(toast.parentElement){toast.parentElement.removeChild(toast);}},300);}function handleApiError(error,defaultMessage = '请求失败'){console.error('API Error:',error);let message = defaultMessage;if(error.response){if(error.response.data && error.response.data.message){message = error.response.data.message;}else if(error.response.status === 401){message = '未授权，请重新登录';setTimeout(()=>{window.location.href = '/login';},2000);}else if(error.response.status === 403){message = '没有权限执行此操作';}else if(error.response.status === 404){message = '请求的资源不存在';}else if(error.response.status === 500){message = '服务器内部错误';}}else if(error.request){message = '网络错误，请检查网络连接';}else{message = error.message || defaultMessage;}showToast(message,'error');return message;}function previewImage(input,previewId){const preview = document.getElementById(previewId);if(!preview || !input || !input.files || !input.files[0])return;const reader = new FileReader();reader.onload = function(e){const img = preview.querySelector('img')|| document.createElement('img');img.src = e.target.result;img.style.maxWidth = '100%';img.style.maxHeight = '200px';if(!preview.querySelector('img')){preview.appendChild(img);}};reader.readAsDataURL(input.files[0]);}function debounce(func,wait){let timeout;return function executedFunction(...args){const later =()=>{clearTimeout(timeout);func(...args);};clearTimeout(timeout);timeout = setTimeout(later,wait);};}function throttle(func,limit){let inThrottle;return function(...args){if(!inThrottle){func.apply(this,args);inThrottle = true;setTimeout(()=> inThrottle = false,limit);}};}function formatFileSize(bytes){if(bytes === 0)return '0 B';const k = 1024;const sizes =['B','KB','MB','GB','TB'];const i = Math.floor(Math.log(bytes)/ Math.log(k));return Math.round(bytes / Math.pow(k,i)* 100)/ 100 + ' ' + sizes[i];}function formatDate(date){if(!date)return '';const d = new Date(date);return d.toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});}function lazyLoadImages(){const images = document.querySelectorAll('img[data-src]');const imageObserver = new IntersectionObserver((entries,observer)=>{entries.forEach(entry =>{if(entry.isIntersecting){const img = entry.target;img.src = img.dataset.src;img.removeAttribute('data-src');observer.unobserve(img);}});});images.forEach(img => imageObserver.observe(img));}document.addEventListener('DOMContentLoaded',function(){initToastContainer();lazyLoadImages();window.addEventListener('error',function(e){console.error('Global error:',e.error);});window.addEventListener('unhandledrejection',function(e){console.error('Unhandled promise rejection:',e.reason);});});window.showLoading = showLoading;window.hideLoading = hideLoading;window.showToast = showToast;window.handleApiError = handleApiError;window.previewImage = previewImage;window.debounce = debounce;window.throttle = throttle;window.formatFileSize = formatFileSize;window.formatDate = formatDate;window.lazyLoadImages = lazyLoadImages;